import sys, itertools, random
sys.path.insert(0,'source')
from selfies.utils.matching_utils import find_perfect_matching

def brute(g):
    n=len(g)
    # backtracking perfect matching
    def rec(unmatched):
        if not unmatched:
            return {}
        u=min(unmatched)
        for v in g[u]:
            if v in unmatched:
                rest=set(unmatched); rest.remove(u); rest.remove(v)
                res=rec(rest)
                if res is not None:
                    res[u]=v; res[v]=u
                    return res
        return None
    res=rec(set(range(n)))
    if res is None: return None
    return [res.get(i) for i in range(n)]

for n in range(1,9):
    # enumerate all simple graphs? random enough
    for trial in range(2000):
        edges=[]
        for i in range(n):
            for j in range(i+1,n):
                if random.random()<0.35:
                    edges.append((i,j))
        g=[[] for _ in range(n)]
        for a,b in edges:
            g[a].append(b); g[b].append(a)
        m1=find_perfect_matching([list(x) for x in g])
        m2=brute(g)
        ok1 = (m1 is None) == (m2 is None)
        if m1 is not None and m2 is not None:
            # verify matching
            if any(m1[i] is None for i in range(n)) or any(m1[m1[i]]!=i for i in range(n)) or any(m1[i] not in g[i] for i in range(n)):
                ok1=False
        if not ok1:
            print('MISMATCH',n,trial,g,m1,m2)
            raise SystemExit
print('all ok')
